#define _CRT_SECURE_NO_WARNINGS
#include <stdio.h>

int main(void) {
    int choice;
    printf("1 Play  2 Scores  3 Quit: ");
    scanf("%d", &choice);

    switch (choice) {
        case 1:
            printf("Starting...\n");
            break;
        case 2:
            printf("High scores\n");
            break;
        case 3:
            printf("Bye\n");
            break;
        default:
            printf("Not an option\n");
            break;
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int lives = 3;
    while (lives > 0) {
        printf("Lives: %d\n", lives);
        lives = lives - 1;
    }
    printf("Game over\n");

    for (int i = 1; i <= 3; i++) {
        printf("Wave %d\n", i);
    }
    return 0;
}

